"""Shared presentation for the calculation-studio portal. No source writes."""
EXTRA_CSS="""
:root{--ink:#17274a;--muted:#526384;--blue:#254bc1;--amber:#f2b64e;--paper:#f8f9ff;--line:#dbe1f0}
body{background-color:var(--paper);background-image:linear-gradient(#2449af09 1px,transparent 1px),linear-gradient(90deg,#2449af09 1px,transparent 1px);background-size:24px 24px;color:var(--ink)}
header{background:#17274a;color:#fff;box-shadow:0 3px 12px #14234b20}header strong{letter-spacing:.035em}header .brand-line{display:flex;align-items:center;gap:9px}header .brand-mark{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#f2b64e;color:#17274a;font-size:22px;font-weight:800}nav a[aria-current=page]{background:#f2b64e;color:#17274a}a{color:#254bc1}main{padding-top:20px}.sub,.caption{color:var(--muted)}
.studio-hero{position:relative;overflow:hidden;min-height:142px;border:1px solid #dbe1f0;background:linear-gradient(120deg,#e8edff,#fff 72%);border-radius:18px;padding:20px;margin:0 0 18px;isolation:isolate}.studio-hero h2{font-size:clamp(1.2rem,4vw,1.85rem);max-width:75%;margin:0 0 10px}.equation{font:600 clamp(.8rem,2.5vw,1rem)/1.6 ui-monospace,monospace;color:#254bc1}.math-grid{position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:.35;background:repeating-linear-gradient(0deg,transparent 0 23px,#bdccff 23px 24px),repeating-linear-gradient(90deg,transparent 0 23px,#bdccff 23px 24px)}
.mascot-track{position:absolute;bottom:9px;left:0;right:0;height:60px;pointer-events:none}.mascot{position:absolute;width:56px;height:56px;left:calc(100% - 70px);animation:calc-roam 16s ease-in-out infinite alternate;filter:drop-shadow(0 4px 2px #18284b22)}@keyframes calc-roam{0%,15%{transform:translateX(0) rotate(-5deg)}48%{transform:translateX(-38px) translateY(-8px) rotate(6deg)}85%,100%{transform:translateX(-6px) rotate(-4deg)}}@media(min-width:700px){@keyframes calc-roam{0%,15%{transform:translateX(0) rotate(-5deg)}48%{transform:translateX(-150px) translateY(-12px) rotate(5deg)}85%,100%{transform:translateX(-20px) rotate(-3deg)}}}
.motion-off .mascot{animation:none!important}.motion-toggle{font-size:.73rem;background:transparent;border:1px solid #c4cfe9;color:#526384;border-radius:6px;padding:4px 7px;position:absolute;right:10px;top:9px;cursor:pointer}
.overview-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:14px}.overview-tile{display:block;background:white;border:1px solid var(--line);border-radius:13px;padding:14px;text-decoration:none;color:var(--ink);min-width:0}.overview-tile strong{display:block;font-size:1.75rem;line-height:1.1;color:#254bc1;font-variant-numeric:tabular-nums}.overview-tile b{display:block;margin-top:5px;font-size:.92rem}.overview-tile small{display:block;color:var(--muted);font-size:.76rem;margin-top:4px}.overview-tile:hover{border-color:#254bc1}.section-card,details.source-group{background:white;border:1px solid var(--line);border-radius:13px;padding:14px;margin:12px 0}.source-group summary{font-weight:700;cursor:pointer;min-height:32px}.source-group .count{color:#526384;font-size:.8rem;float:right;font-weight:500}.source-group ul{margin:8px 0;padding-left:20px}.source-group li{padding:5px 0}.table-scroll{overflow-x:auto;max-width:100%;border:1px solid var(--line);border-radius:10px}.register-table{width:100%;border-collapse:collapse;text-align:left;font-size:.9rem;background:white}.register-table th{background:#edf1ff;color:var(--ink);text-align:left}.register-table th,.register-table td{padding:10px 12px;border-bottom:1px solid #e4e8f4;vertical-align:top}.register-table td a{font-weight:650}.register-table td:first-child{min-width:135px;overflow-wrap:anywhere}.register-table td:last-child{white-space:nowrap}.register-table tr:last-child td{border:0}.filter-row{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0;align-items:center}.filter-row input,.filter-row select,.filter-row button{font:inherit;padding:9px 11px;border:1px solid #c4cfe9;border-radius:8px;background:white;color:var(--ink);min-width:0}.filter-row input{flex:1 1 190px}.filter-row select{max-width:100%}.project{border-color:var(--line);box-shadow:0 2px 5px #14234b08}.source-row{border-color:#e4e8f4}.source-row small{color:var(--muted)}.org h2{color:#254bc1}.formula-strip{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}.formula-strip span{border:1px solid #cbd5f2;background:#eef2ff;padding:7px 10px;border-radius:8px;font:600 .82rem ui-monospace,monospace;color:#254bc1}.rate-item{display:block;text-align:left;border:0;background:none;color:#254bc1;text-decoration:underline;cursor:pointer;font:inherit;padding:0}.evidence-dialog{width:min(860px,94vw);max-height:90vh;overflow:auto;border:1px solid #c4cfe9;border-radius:14px;padding:20px;background:white;color:var(--ink)}.evidence-dialog::backdrop{background:#17274a99}.evidence-dialog img{width:100%;height:auto;display:block;margin:12px 0}.evidence-dialog button{float:right;background:#17274a;color:white;border:0;border-radius:8px;padding:8px 12px;cursor:pointer}.evidence-dialog p{white-space:pre-wrap;overflow-wrap:anywhere}.jp-workbook-gallery{border-color:#dbe1f0!important;background:#f0f3ff!important;color:#17274a!important}.jp-wb-card{border-top-color:#254bc1!important}.jp-wb-card[data-active=true]{border-color:#254bc1!important}.jp-wb-card a{color:#254bc1!important}.jp-wb-scene{height:245px!important}.jp-wb-card{height:204px!important}.footer{border-color:#dbe1f0}
@media(min-width:720px){.overview-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:480px){.studio-hero{padding:14px;min-height:140px}.overview-tile{padding:11px}.register-table th,.register-table td{padding:8px;font-size:.82rem}}@media(prefers-reduced-motion:reduce){.mascot{animation:none!important}}
.mascot-lane{position:relative;isolation:isolate;height:64px;overflow:hidden;border:1px solid #dbe1f0;border-radius:11px;margin:0 0 14px;background:linear-gradient(90deg,#e9edff,#fff,#e9edff)}.mascot-lane .lane-equation{position:absolute;left:12px;bottom:8px;color:#254bc156;font:600 1.05rem ui-monospace,monospace;letter-spacing:.1em}.mascot-lane .mascot-track{bottom:0;height:55px}.mascot-lane .mascot{left:12px;width:48px;height:48px;animation:calc-travel 15s ease-in-out infinite alternate}.mascot-lane .motion-toggle{z-index:1;background:#ffffffed;font-size:.7rem;top:4px;right:6px;padding:3px 6px}@keyframes calc-travel{0%,8%{left:12px;transform:rotate(-5deg)}48%{transform:translateY(-3px) rotate(4deg)}92%,100%{left:calc(100% - 60px);transform:rotate(5deg)}}.studio-hero{min-height:0}.studio-hero h2{max-width:100%}@media(prefers-reduced-motion:reduce){.mascot-lane .mascot{animation:none!important}}

/* Calc flies around the visible page, not a clipped horizontal lane. */
.mascot-track{position:fixed;inset:0;width:100%;height:100%;z-index:40;pointer-events:none;overflow:clip;--fly-left:8px;--fly-right:calc(100vw - 66px);--fly-top:min(150px,29vh);--fly-bottom:max(var(--fly-top),calc(100vh - 100px));--fly-middle:calc((var(--fly-top) + var(--fly-bottom))/2)}
@supports(height:100dvh){.mascot-track{--fly-top:min(150px,29dvh);--fly-bottom:max(var(--fly-top),calc(100dvh - 100px))}}
.mascot-track .mascot{position:absolute;top:0;left:0;width:56px;height:56px;opacity:.94;will-change:transform;animation:calc-free-flight 25s linear infinite}
@keyframes calc-free-flight{
0%,100%{transform:translate3d(var(--fly-left),var(--fly-top),0) rotate(-9deg)}
12%{transform:translate3d(calc(25vw - 10px),calc(var(--fly-top) + 25px),0) rotate(10deg)}
24%{transform:translate3d(var(--fly-right),var(--fly-middle),0) rotate(15deg)}
36%{transform:translate3d(calc(72vw - 35px),var(--fly-bottom),0) rotate(-12deg)}
48%{transform:translate3d(calc(40vw - 20px),calc(var(--fly-bottom) - 28px),0) rotate(-12deg)}
60%{transform:translate3d(var(--fly-left),var(--fly-middle),0) rotate(13deg)}
72%{transform:translate3d(calc(50vw - 28px),var(--fly-top),0) rotate(10deg)}
84%{transform:translate3d(var(--fly-right),calc(var(--fly-top) + 32px),0) rotate(-11deg)}
92%{transform:translate3d(calc(30vw - 15px),var(--fly-middle),0) rotate(-15deg)}
}
header .motion-toggle{position:static;flex-shrink:0;margin-left:auto;color:#fff;background:#24395f;border-color:#7385ab;font-size:.7rem;min-height:28px}
.motion-off .mascot-track .mascot{animation:none!important;transform:translate3d(var(--fly-right),var(--fly-bottom),0)}
@media(max-width:480px){.mascot-track .mascot{width:46px;height:46px}header .brand-line{flex-wrap:wrap}header strong{font-size:.9rem}header .motion-toggle{font-size:.67rem}}
@media(prefers-reduced-motion:reduce){.mascot-track .mascot{animation:none!important;transform:translate3d(var(--fly-right),var(--fly-bottom),0)}}

"""
MASCOT="""<div class="mascot-track" aria-hidden="true"><svg class="mascot" viewBox="0 0 72 72"><path d="M20 53l-8 9m38-9 8 9" stroke="#17274a" stroke-width="5" stroke-linecap="round"/><path d="M16 33 5 27m51 6 11-6" stroke="#17274a" stroke-width="4" stroke-linecap="round"/><rect x="16" y="5" width="40" height="52" rx="11" fill="#254bc1" stroke="#17274a" stroke-width="2"/><rect x="22" y="11" width="28" height="17" rx="5" fill="#fff"/><circle cx="30" cy="18" r="2.8" fill="#17274a"/><circle cx="42" cy="18" r="2.8" fill="#17274a"/><path d="M32 23q4 4 8 0" stroke="#17274a" fill="none" stroke-width="1.5"/><g fill="#dce5ff"><rect x="23" y="34" width="7" height="6" rx="1.5"/><rect x="33" y="34" width="7" height="6" rx="1.5"/><rect x="23" y="44" width="7" height="6" rx="1.5"/><rect x="33" y="44" width="7" height="6" rx="1.5"/></g><rect x="43" y="34" width="7" height="16" rx="2" fill="#f2b64e"/><path d="M44.5 40h4m-4 4h4" stroke="#17274a" stroke-width="1.4"/></svg></div>"""
HOME_JS=r"""
(()=>{const root=document.getElementById('homeOverview');const reg=document.getElementById('registerDirectory');const motion=document.querySelector('.motion-toggle');if(motion){motion.addEventListener('click',()=>{const off=document.body.classList.toggle('motion-off');motion.textContent=off?'Resume mascot':'Pause mascot';motion.setAttribute('aria-pressed',String(off));});}if(!root&&!reg)return;
const el=(tag,p,t,c)=>{const e=document.createElement(tag);if(t!==undefined)e.textContent=t;if(c)e.className=c;p.append(e);return e;};
const link=(p,c)=>{const a=el('a',p,c.title);a.href=c.url;a.target='_blank';a.rel='noopener noreferrer';return a;};
const safe=c=>/^https:\/\/docs\.google\.com\/spreadsheets\/d\/[A-Za-z0-9_-]{20,160}\/edit$/.test(c.url);
fetch('data/'+(root?'home':'registers')+'-links.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{
const groups=d.groups;if(!Array.isArray(groups)||!groups.every(g=>g.cards.every(safe)))throw Error();
if(root){root.replaceChildren();const tiles=el('div',root,undefined,'overview-grid');const sections=[['Rates',2,'rate-sources.html','Rate libraries & PDF evidence'],['Projects',null,'projects.html','Company & project summaries'],['Quantities',groups[3].cards.length+groups[4].cards.length,'quantity-workbooks.html','BBS & measurements'],['Registers',groups[0].cards.length-2+groups[1].cards.length+groups[2].cards.length,'finance.html','Payments, bills & workforce']];for(const [name,count,url,detail] of sections){const a=el('a',tiles,undefined,'overview-tile');a.href=url;el('strong',a,count===null?'↗':String(count));el('b',a,name);el('small',a,detail);}
const all=el('details',root,undefined,'source-group');el('summary',all,'View all '+groups.reduce((n,g)=>n+g.cards.length,0)+' workbook links');for(const g of groups){const sub=el('details',all,undefined,'source-group');el('summary',sub,g.title+' ('+g.cards.length+')');const ul=el('ul',sub);for(const c of g.cards)link(el('li',ul),c);}return;}
reg.replaceChildren();const filters=el('div',reg,undefined,'filter-row'),search=el('input',filters);search.type='search';search.placeholder='Find a register…';search.setAttribute('aria-label','Search registers');const select=el('select',filters);select.setAttribute('aria-label','Register category');select.add(new Option('All categories',''));for(const g of groups)select.add(new Option(g.title,g.key));const status=el('p',reg,undefined,'caption');status.setAttribute('aria-live','polite');const out=el('div',reg);
function render(){out.replaceChildren();const q=search.value.toLowerCase().trim();let count=0;for(const g of groups){if(select.value&&select.value!==g.key)continue;const rows=g.cards.filter(c=>(c.title+' '+c.detail+' '+c.key).toLowerCase().includes(q));if(!rows.length)continue;const det=el('details',out,undefined,'source-group');det.open=Boolean(q||select.value||g.key==='finance');el('summary',det,g.title+' ('+rows.length+')');const table=el('table',el('div',det,undefined,'table-scroll'),undefined,'register-table');const tr=el('tr',el('thead',table));for(const t of ['Workbook','Purpose','Open'])el('th',tr,t);const body=el('tbody',table);for(const c of rows){const row=el('tr',body);el('td',row,c.title);el('td',row,c.detail);const a=link(el('td',row),c);a.textContent='Sheet ↗';count++;}}status.textContent=count+' matching registers';}search.addEventListener('input',render);select.addEventListener('change',render);render();
}).catch(()=>{(root||reg).textContent='Workbook directory unavailable. Open the Source Index below.'});})();
"""
RATE_JS=r"""
(()=>{const root=document.getElementById('rateEvidence');if(!root)return;const el=(tag,p,t,c)=>{const e=document.createElement(tag);if(t!==undefined)e.textContent=t;if(c)e.className=c;p.append(e);return e;};
const read=async path=>{const r=await fetch(path);if(!r.ok)throw Error('Source file unavailable');if(path.endsWith('.gz')){const b=await r.arrayBuffer();if(new Uint8Array(b)[0]===31){return new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).json()}return JSON.parse(new TextDecoder().decode(b));}return r.json()};
Promise.all([read('data/rate-source-derived.v0.5.15.json'),read('data/contractor-work-items.v0.1.json'),read('data/contractor-short-labels.v0.1.json')]).then(([manifest,road,short])=>{
root.replaceChildren();const filters=el('div',root,undefined,'filter-row'),source=el('select',filters),mode=el('select',filters),search=el('input',filters);source.setAttribute('aria-label','Rate source');mode.setAttribute('aria-label','Reading type');search.type='search';search.placeholder='Search item, unit, norm or page';search.setAttribute('aria-label','Search rate items');source.add(new Option('Illustrated road-work handbook','road'));for(const s of manifest.sources)source.add(new Option(s.label,s.id));const status=el('p',root,undefined,'caption');status.setAttribute('aria-live','polite');const wrap=el('div',root,undefined,'table-scroll'),table=el('table',wrap,undefined,'register-table'),tr=el('tr',el('thead',table));for(const x of ['Item / description','Unit','Value / source','Page'])el('th',tr,x);const tbody=el('tbody',table),pager=el('div',root,undefined,'filter-row'),prev=el('button',pager,'← Previous'),next=el('button',pager,'Next →');prev.type=next.type='button';
const dialog=el('dialog',root,undefined,'evidence-dialog');const close=el('button',dialog,'Close');close.addEventListener('click',()=>dialog.close());const detail=el('div',dialog);const labels=new Map(short.items.map(r=>[r.item_id,r.short_description]));let rows=[],offset=0,token=0,active=null;const size=20;const cache=new Map();const fmt=new Intl.NumberFormat('en-IN',{maximumFractionDigits:4});
function describe(r){return source.value==='road'?(labels.get(r.id)||r.description):r.description||r.text||r.id||'Unresolved text';}
function show(r){detail.replaceChildren();el('h2',detail,describe(r));if(source.value==='road'){el('p',detail,r.description);el('p',detail,'Norm '+(r.norm_no||'Unresolved')+' · Clause '+(r.specification_clause_no||'Unresolved')+' · '+(r.unit||'Unresolved')+' · '+(r.rate_npr===null?'Unresolved':'NPR '+fmt.format(r.rate_npr)));const p=road.summary_pages.indexOf(r.source_page)+1;const a=el('a',detail,'Open original PDF excerpt · page '+r.source_page);a.href=road.summary_pdf+'#page='+p;a.target='_blank';a.rel='noopener noreferrer';const img=el('img',detail);img.src=road.page_image_pattern.replace('{page}',String(r.source_page).padStart(3,'0'));img.alt='Original handbook scan, PDF page '+r.source_page;el('p',detail,'Provisional source transcription; verify against the original scan.');}else{el('p',detail,'Source page '+(r.page??'Unresolved')+' · '+(r.status||'Review pending'));if(r.text&&r.text!==r.description)el('p',detail,r.text);if(r.basis)el('p',detail,r.basis);if(active?.private_fields_withheld)el('p',detail,'Private quotation fields withheld.');}dialog.showModal();}
function render(){const q=search.value.toLowerCase().trim();const selected=rows.filter(r=>[describe(r),r.description,r.unit,r.norm_no,r.serial_no,r.page,r.source_page].join(' ').toLowerCase().includes(q));offset=Math.min(offset,Math.max(0,Math.floor((selected.length-1)/size)*size));tbody.replaceChildren();for(const r of selected.slice(offset,offset+size)){const row=el('tr',tbody),cell=el('td',row),b=el('button',cell,describe(r),'rate-item');b.type='button';b.addEventListener('click',()=>show(r));el('td',row,r.unit||'—');const v=source.value==='road'?r.rate_npr:r.value;el('td',row,active?.private_fields_withheld?'Private':v===null||v===undefined?'Unresolved':fmt.format(v));el('td',row,String(r.source_page??r.page??'—'));}status.textContent=selected.length+' results · '+(selected.length?offset+1:0)+'–'+Math.min(offset+size,selected.length)+' · '+(source.value==='road'?'provisional historical transcription':mode.value==='candidates'?'numeric candidates — not all prices':'source observations; review pending');prev.disabled=offset===0;next.disabled=offset+size>=selected.length;}
async function load(){const current=++token;offset=0;status.textContent='Loading source…';tbody.replaceChildren();try{active=manifest.sources.find(s=>s.id===source.value)||null;if(!active){rows=road.items;render();return;}const key=source.value+':'+mode.value;if(!cache.has(key)){const chunks=await Promise.all(active[mode.value].map(read));cache.set(key,chunks.flat());}if(current!==token)return;rows=cache.get(key);render();}catch(e){if(current===token)status.textContent='Unable to load this source. '+e.message;}}
function change(){mode.replaceChildren();const s=manifest.sources.find(s=>s.id===source.value);if(!s){mode.add(new Option('Illustrated items','road'));}else{if(s.entries.length)mode.add(new Option('Source observations','entries'));if(s.candidates.length)mode.add(new Option('Numeric candidates','candidates'));if(s.pages.length)mode.add(new Option('Page transcripts','pages'));}load();}
source.addEventListener('change',change);mode.addEventListener('change',load);search.addEventListener('input',()=>{offset=0;render()});prev.addEventListener('click',()=>{offset=Math.max(0,offset-size);render()});next.addEventListener('click',()=>{offset+=size;render()});change();
}).catch(()=>{root.textContent='Extracted reference unavailable. Use the PDF Rate Observations Google Sheet above.'});})();
"""
